from solution import merge_intervals


def test_basic_overlap():
    assert merge_intervals([(1, 3), (2, 4)]) == [(1, 4)]


def test_unsorted():
    assert merge_intervals([(5, 6), (1, 2)]) == [(1, 2), (5, 6)]


def test_touching():
    assert merge_intervals([(1, 3), (3, 5)]) == [(1, 5)]


def test_empty_input():
    assert merge_intervals([]) == []


def test_empty_intervals_dropped():
    assert merge_intervals([(3, 3), (5, 2)]) == []


def test_empty_interval_does_not_bridge():
    assert merge_intervals([(1, 2), (2, 2), (3, 4)]) == [(1, 2), (3, 4)]


def test_empty_inside_other_ignored():
    assert merge_intervals([(1, 10), (5, 5)]) == [(1, 10)]


def test_nested():
    assert merge_intervals([(1, 10), (2, 3), (4, 5)]) == [(1, 10)]


def test_lists_input_and_tuple_output():
    r = merge_intervals([[1, 3], [2, 5]])
    assert r == [(1, 5)]
    assert all(isinstance(x, tuple) for x in r)


def test_not_modified():
    data = [[5, 6], [1, 3], [2, 4]]
    copy = [list(x) for x in data]
    merge_intervals(data)
    assert data == copy


def test_negative():
    assert merge_intervals([(-5, -1), (-3, 2), (2, 4)]) == [(-5, 4)]


def test_chain_merge():
    assert merge_intervals([(1, 2), (2, 3), (3, 4), (10, 11)]) == [(1, 4), (10, 11)]


def test_duplicates():
    assert merge_intervals([(1, 2), (1, 2)]) == [(1, 2)]


def test_same_start_different_end():
    assert merge_intervals([(1, 5), (1, 3)]) == [(1, 5)]


def test_gap_of_one():
    assert merge_intervals([(1, 2), (3, 4)]) == [(1, 2), (3, 4)]
